/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `projectquotations_after_insert` AFTER INSERT ON `projectquotations` FOR EACH ROW BEGIN
	UPDATE projects SET TOTAMOUNT = TOTAMOUNT + NEW.TOTALCOST, FINALAMOUNT = FINALAMOUNT + NEW.FINALCOST WHERE PROJECTID =  NEW.PROJECT;
END */;;
DELIMITER ;
